'use strict';
const $=s=>document.querySelector(s),dialog=$('#dialog');
class MoonwindGame{
 constructor(){this.keys=new Set();this.p=this.fresh();this.saveOK=true;this.load();this.p.expeditions??=Array(12).fill(0);this.p.job??='traveler';if(this.p.activity){this.p.x=11*48;this.p.y=28*48;this.p.activity=null;}this.renderer=new MW.Renderer($('#game'));this.enemies=[];this.fx=[];this.telegraphs=[];this.collected=new Set();this.cool={attack:0,skill:0,dash:0};this.face=0;this.invuln=0;this.slash=0;this.slashSkill=false;this.moving=false;this.tracking=true;this.time=0;this.lastInput=0;this.saveTimer=0;this.uiTimer=0;this.event=null;this.tower=null;this.dungeon=null;this.escort=null;this.sound=false;this.paused=false;this.enter(this.p.region,true);this.bind();this.ui();let last=performance.now();const loop=now=>{const dt=Math.max(0,Math.min((now-last)/1000,.05));last=now;if(!document.hidden&&!dialog.open&&!this.paused)this.update(dt);this.renderer.draw(this,dt);requestAnimationFrame(loop);};requestAnimationFrame(loop);}
 fresh(){return{version:2,job:'traveler',region:0,x:11*48,y:28*48,hp:180,mp:100,level:1,xp:0,gold:90,bag:{potion:8,ether:3,meal:1,ward:1,ore:0,herb:0},owned:[],equip:{weapon:null,armor:null,charm:null},upgrade:0,unlocked:0,progress:Array.from({length:12},()=>({step:0,count:0,seen:[],memories:[],chests:[],boss:false})),side:Array.from({length:12},()=>[0,0,0].map(()=>({accepted:false,done:false,count:0}))),seconds:0,towerBest:0,towerRewards:[],buffs:{meal:0,ward:0},log:[]};}
 valid(s){if(s?.job!==undefined&&!Object.hasOwn(MW.jobs,s.job))return false;if(!s||s.version!==2||!Number.isInteger(s.region)||s.region<0||s.region>11||!Number.isFinite(s.x)||!Number.isFinite(s.y)||s.x<96||s.x>3744||s.y<96||s.y>2496||!Number.isInteger(s.level)||s.level<1||s.level>99||!Array.isArray(s.progress)||s.progress.length!==12||!Array.isArray(s.side)||s.side.length!==12)return false;for(const k of ['hp','mp','xp','gold','seconds','upgrade','unlocked','towerBest'])if(!Number.isFinite(s[k])||s[k]<0)return false;if(s.hp<=0||s.mp>100||s.upgrade>10||s.unlocked>11||s.towerBest>30||s.region>s.unlocked)return false;for(const q of s.progress)if(!q||!Number.isInteger(q.step)||q.step<0||q.step>9||!Number.isFinite(q.count)||q.count<0||!['seen','memories','chests'].every(k=>Array.isArray(q[k])&&q[k].every(v=>typeof v==='string')))return false;for(const r of s.side)if(!Array.isArray(r)||r.length!==3||r.some(q=>!q||!Number.isFinite(q.count)||q.count<0))return false;if(s.expeditions!==undefined&&(!Array.isArray(s.expeditions)||s.expeditions.length!==12||s.expeditions.some(n=>!Number.isInteger(n)||n<0||n>6)))return false;return s.bag&&['potion','ether','meal','ward','ore','herb'].every(k=>Number.isFinite(s.bag[k])&&s.bag[k]>=0)&&s.equip&&['weapon','armor','charm'].every(k=>s.equip[k]===null||MW.items.some(i=>i.id===s.equip[k]&&i.type===k&&(!i.job||i.job===s.job)))&&Array.isArray(s.owned)&&s.owned.every(id=>MW.items.some(i=>i.id===id))&&s.buffs&&['meal','ward'].every(k=>Number.isFinite(s.buffs[k])&&s.buffs[k]>=0)&&Array.isArray(s.towerRewards)&&s.towerRewards.every(n=>Number.isInteger(n)&&n>=1&&n<=30)&&Array.isArray(s.log);}
 load(){for(const key of ['moonwind-v2','moonwind-v2-backup']){try{const raw=localStorage.getItem(key);if(!raw)continue;const data=JSON.parse(raw);if(this.valid(data)){this.p=data;this.p.job??='traveler';if(key.endsWith('backup'))this.p.log.push('기기의 보조 저장 사본에서 여정을 복구했습니다.');return;}}catch{this.saveOK=false;}}try{const old=JSON.parse(localStorage.getItem('moonwind-v1'));if(old&&Number.isFinite(old.gold)&&old.gold>=0){this.p.gold+=Math.min(old.gold,5000);this.p.bag.potion+=Math.min(Math.max(Number(old.potions)||0,0),99);this.p.log.push('이전 여정의 소지금과 물약을 계승했습니다. 새 이야기는 1장부터 시작합니다.');}}catch{this.saveOK=false;}}
 save(){this.p.activity=this.dungeon?'dungeon':this.tower?'tower':null;try{let previous=null;try{const raw=localStorage.getItem('moonwind-v2');if(raw&&this.valid(JSON.parse(raw)))previous=raw;}catch{}const stamp=Date.now(),snapshot=JSON.stringify({...this.p,savedAt:stamp});localStorage.setItem('moonwind-v2',snapshot);this.p.savedAt=stamp;this.saveOK=true;try{localStorage.setItem('moonwind-v2-backup',previous||snapshot);}catch{}}catch{this.saveOK=false;}}
 stats(){const job=MW.jobs[this.p.job]||MW.jobs.traveler,get=t=>MW.items.find(i=>i.id===this.p.equip[t])||{};return{hp:180+job.hp+(this.p.level-1)*16+(get('charm').hp||0),atk:18+job.atk+(this.p.level-1)*4+(get('weapon').atk||0)+this.p.upgrade*5,def:2+job.def+Math.floor(this.p.level/2)+(get('armor').def||0)};}
 needXP(){return 65+this.p.level*32;}
 reward(xp,gold){this.p.xp+=xp;this.p.gold+=gold;while(this.p.level<99&&this.p.xp>=this.needXP()){this.p.xp-=this.needXP();this.p.level++;this.p.hp=this.stats().hp;this.p.mp=100;this.notify(`레벨 ${this.p.level} · 생명과 기력 회복`);this.beep(780);}this.save();}
 q(){return this.p.progress[this.p.region];}step(){return MW.steps[this.q().step];}
 required(){const s=this.step();return s?.kind==='kill'?36+this.p.region*4:s?.count||1;}
 enter(region,keep=false){this.p.region=region;this.world=MW.makeWorld(region);this.renderer.setWorld(this.world);this.enemies=[];this.telegraphs=[];this.fx=[];this.event=null;this.escort=null;this.tower=null;this.dungeon=null;this.collected=new Set([...this.q().memories,...this.q().chests]);if(!keep||this.world.solid(this.p.x,this.p.y)){this.p.x=11*48;this.p.y=28*48;}MW.enemySpawns.forEach(([x,y],i)=>this.spawn(x*48,y*48,{type:i%3,seed:i,home:true}));if(!this.q().boss)this.spawn(69*48,20*48,{boss:true,type:3});this.save();this.ui();}
 spawn(x,y,opts={}){if(this.world.solid(x,y)){for(let d=1;d<8;d++)if(!this.world.solid(x+d*48,y)){x+=d*48;break;}}const r=this.p.region,tower=this.tower?.floor||0,expedition=this.dungeon?.floor||0,hp=opts.boss?(850+r*210+tower*45):(170+r*55+tower*16);const e={x,y,homeX:x,homeY:y,hp,max:hp,dead:0,cd:1,cast:0,boss:false,type:0,seed:this.enemies.length,home:false,event:false,tower:false,name:MW.regions[r].boss,...opts};if(opts.tower){e.hp=e.max=Math.max(e.max,this.stats().atk*(e.boss?45:8+tower*.35));}if(opts.expedition){e.hp=e.max=Math.max(e.max,this.stats().atk*(e.boss?55:9+expedition));}this.enemies.push(e);return e;}
 notify(msg){$('#message').textContent=msg;$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
 beep(f){if(!this.sound)return;try{this.audio??=new AudioContext();const o=this.audio.createOscillator(),g=this.audio.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.035,this.audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.audio.currentTime+.13);o.connect(g).connect(this.audio.destination);o.start();o.stop(this.audio.currentTime+.15);}catch{}}
 effect(x,y,text,color='#ffe4a1'){this.fx.push({x,y,text,color,life:1});}
 move(o,dx,dy){if(!this.world.solid(o.x+dx,o.y))o.x+=dx;if(!this.world.solid(o.x,o.y+dy))o.y+=dy;}
 attack(skill=false){this.lastInput=this.time;if(dialog.open||document.hidden||this.paused||this.cool.attack>0)return;if(skill&&(this.cool.skill>0||this.p.mp<25)){if(this.p.mp<25)this.notify('기력이 부족합니다. 기력약(2)을 사용하세요.');return;}this.cool.attack=skill?.6:.38;this.slash=skill?.45:.22;this.slashSkill=skill;const weapon=MW.items.find(i=>i.id===this.p.equip.weapon),kind=weapon?.kind||'weapon';this.strike={x:this.p.x,y:this.p.y,face:this.face,job:this.p.job,kind:skill?'skill':this.p.equip.weapon?kind:'unarmed'};const range=skill?(this.p.job==='warrior'?160:this.p.job==='traveler'?150:280):weapon?.kind==='bow'?230:weapon?.kind==='staff'?200:80;if(skill){this.cool.skill=4;this.p.mp-=25;}this.beep(skill?650:280);for(const e of this.enemies){const dx=e.x-this.p.x,dy=e.y-this.p.y,distance=Math.hypot(dx,dy),forward=[[0,1],[1,0],[0,-1],[-1,0]][this.face];if(e.dead||distance>range||((kind==='bow'||kind==='staff')&&distance>80&&(dx*forward[0]+dy*forward[1])/distance<.4))continue;let damage=Math.round(this.stats().atk*(skill?2.7:1)*(this.p.buffs.meal>0?1.15:1));const critical=MW.hash(Math.floor(this.time*100),e.seed)%10===0;if(critical)damage=Math.round(damage*1.6);e.hp-=damage;this.effect(e.x,e.y-40,(critical?'✦ ':'')+damage,{unarmed:'#efc39b',weapon:'#ffe2a3',bow:'#d9edb5',staff:'#c9c0f4',skill:'#a9eced'}[this.strike.kind]);if(e.hp<=0)this.kill(e);}this.ui();}
 kill(e){e.dead=e.home?18:Infinity;const r=this.p.region;this.reward(e.boss?210+r*45:12+r*3,e.boss?150+r*55:8+r*2);if(MW.hash(e.seed,Math.floor(this.time))%4===0)this.p.bag.ore++;if(!e.boss&&!e.tower&&!e.expedition){if(this.step()?.kind==='kill')this.count('kill');const s=this.p.side[r][0];if(s.accepted&&!s.done)s.count++;}if(e.event&&this.event)this.event.kills++;if(e.tower&&this.tower)this.tower.kills++;if(e.boss&&!e.tower&&!e.expedition){this.q().boss=true;this.count('boss');this.notify(`${e.name}의 밤이 끝났습니다.`);}this.save();}
 dash(){if(dialog.open||this.cool.dash>0||this.p.mp<12)return;this.p.mp-=12;this.cool.dash=2;this.invuln=.55;let dx=(this.keys.has('ArrowRight')||this.keys.has('d')?1:0)-(this.keys.has('ArrowLeft')||this.keys.has('a')?1:0),dy=(this.keys.has('ArrowDown')||this.keys.has('s')?1:0)-(this.keys.has('ArrowUp')||this.keys.has('w')?1:0);if(!dx&&!dy)[dx,dy]=[[0,1],[1,0],[0,-1],[-1,0]][this.face];const norm=Math.hypot(dx,dy);for(let i=0;i<22;i++)this.move(this.p,dx/norm*7,dy/norm*7);this.effect(this.p.x,this.p.y-50,'바람걸음','#b9e6e4');}
 use(id){if(!this.p.bag[id]){this.notify('보급품이 없습니다. 물약 상인을 찾아가세요.');return;}if(id==='potion'&&this.p.hp>=this.stats().hp){this.notify('생명력이 가득합니다.');return;}if(id==='ether'&&this.p.mp>=100){this.notify('기력이 가득합니다.');return;}this.p.bag[id]--;if(id==='potion')this.p.hp=Math.min(this.stats().hp,this.p.hp+120);if(id==='ether')this.p.mp=Math.min(100,this.p.mp+80);if(id==='meal'||id==='ward')this.p.buffs[id]=480;this.notify(MW.items.find(i=>i.id===id).name+' 사용');this.save();this.ui();}
 hurt(damage){if(this.invuln>0)return;damage=Math.max(3,damage-this.stats().def);if(this.p.buffs.ward>0)damage=Math.round(damage*.8);this.p.hp-=damage;this.invuln=.45;this.effect(this.p.x,this.p.y-55,'−'+damage,'#ffb3a0');this.beep(140);if(this.p.hp<=0){const fee=Math.min(this.p.gold,30+this.p.region*10);this.p.gold-=fee;this.p.hp=this.stats().hp;this.p.mp=100;this.p.x=11*48;this.p.y=28*48;this.event=null;this.escort=null;if(this.tower||this.dungeon)this.enter(this.p.region);this.enemies=this.enemies.filter(e=>!e.event);this.telegraphs=[];this.notify(`마을에서 구조되었습니다. 치료비 ${fee}냥 · 의뢰 진행 유지`);this.save();}}
 count(kind,n=1){if(this.step()?.kind!==kind)return;this.q().count+=n;if(this.q().count>=this.required())this.advance();}
 advance(){const q=this.q(),s=this.step();if(!s)return;q.step++;q.count=0;q.seen=[];this.reward(60+this.p.region*18,45+this.p.region*12);this.p.log.push(`${MW.regions[this.p.region].name} · ${s.title}`);this.p.log=this.p.log.slice(-120);if(q.step===9){this.p.unlocked=Math.min(11,Math.max(this.p.unlocked,this.p.region+1));this.notify(this.p.region===11?'열두 조각의 달 · 이야기 완수':'달 조각 획득! 다음 지역의 길이 열렸습니다.');}else this.notify('의뢰 완료 · '+s.title+' / 다음: '+this.step().title);this.save();this.ui();}
 show(speaker,title,text,choices=[]){$('#speaker').textContent=speaker;$('#dialogtitle').textContent=title;$('#dialogtext').replaceChildren();if(typeof text==='string'){const p=document.createElement('p');p.textContent=text;$('#dialogtext').append(p);}else $('#dialogtext').append(text);$('#choices').replaceChildren();for(const [label,fn]of choices){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{fn();this.ui();this.save();};$('#choices').append(b);}this.keys.clear();this.resetStick?.();if(!dialog.open)dialog.showModal();}
 primaryMode(){const near=o=>Math.hypot(o.x-this.p.x,o.y-this.p.y)<105;if(this.enemies.some(e=>!e.dead&&Math.hypot(e.x-this.p.x,e.y-this.p.y)<100))return 'attack';if(this.world.npcs.some(near))return 'talk';if(this.world.objects.some(o=>near(o)&&!this.collected.has(o.id)&&(!this.dungeon||o.id==='leave'||!this.dungeon.seals.includes(o.id))))return 'inspect';return 'attack';}
 primaryAction(){if(dialog.open||document.hidden||this.paused)return;if(this.primaryMode()==='attack')this.attack();else{this.keys.delete(' ');this.interact();}}
 interact(){this.lastInput=this.time;if(dialog.open)return;const p=this.p,near=o=>Math.hypot(o.x-p.x,o.y-p.y)<105;const n=this.world.npcs.filter(near).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(n){this.npc(n);return;}if(this.dungeon){this.dungeonInteract();return;}const o=this.world.objects.filter(near).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!o){this.notify('주민·빛나는 조각·표식 가까이에서 E를 누르세요.');return;}if(o.type==='portal'){if(o.next>11){this.show('새벽의 봉우리','여행은 계속된다','이야기를 마쳤다면 의뢰 수첩의 주민 의뢰와 30층 시련의 탑에 도전하세요.');return;}if(o.next>p.unlocked){this.notify('이 지역의 이야기를 완료하면 다음 길이 열립니다.');return;}this.enter(o.next);this.notify(MW.regions[o.next].name+'에 도착했습니다.');return;}if(o.type==='memory'){if(this.collected.has(o.id))return;this.collected.add(o.id);this.q().memories.push(o.id);p.bag.herb+=2;const side=p.side[p.region][1];if(side.accepted&&!side.done)side.count++;this.count('collect');if(this.step()?.kind==='collect'&&this.q().count===0&&this.q().memories.length>=10){this.q().count=10;this.advance();}this.notify(MW.regions[p.region].item+' 수집 · 약초 +2');this.save();return;}if(o.type==='chest'){if(this.collected.has(o.id)){this.notify('이미 연 보물함입니다.');return;}this.collected.add(o.id);this.q().chests.push(o.id);p.gold+=50+p.region*18;p.bag.ore+=2;p.bag.potion++;const side=p.side[p.region][2];if(side.accepted&&!side.done)side.count++;this.notify('보물함 · 소지금, 강화석 2, 회복약 1');this.save();return;}if(o.type==='landmark')this.landmark(o);}
 npc(n){const r=MW.regions[this.p.region],s=this.step();if(n.role==='guide'){if(s?.kind==='talk')this.show(n.name,r.subtitle,r.story,[['여정을 시작한다',()=>{dialog.close();this.count('talk');}]]);else if(s?.kind==='return')this.show(n.name,r.relic,r.after,[['달 조각을 나눈다',()=>{dialog.close();this.count('return');this.p.bag.potion+=3;this.p.bag.ore+=4;}]]);else this.show(n.name,r.subtitle,this.q().step===9?r.after:r.story+'\n\n현재 의뢰: '+s.detail,[['의뢰 수첩',()=>this.journal()]]);}else if(n.role==='shop'||n.role==='weapons')this.shop(n);else if(n.role==='mentor')this.jobMenu();else if(n.role==='smith')this.forge(n);else if(n.role==='side')this.sideMenu(n);else if(n.role==='tower'){this.expeditionMenu(n);return;}else if(n.role==='unused')this.show(n.name,'이름의 시련 · 30층','4개의 전투를 거쳐 다음 층으로 갑니다. 층마다 새로운 보상과 기록을 얻습니다. 5층마다 수호자가 나타납니다. 도전 중에는 여행과 일반 의뢰가 멈춥니다. 쓰러지거나 떠나도 최고 기록과 보상은 유지됩니다. 챕터 3부터 도전할 수 있습니다.',this.p.unlocked>=2?[['탑 도전',()=>{dialog.close();this.startTower(1);}]]:[]);}
 content(){const d=document.createElement('div');d.className='cards';return d;}card(title,description){const d=document.createElement('div');d.className='card';const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=description;d.append(h,p);return d;}button(card,label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{fn();this.save();this.ui();};card.append(b);}
 shop(n){const supplies=n.role!=='weapons',box=this.content(),tier=Math.min(4,1+Math.floor(this.p.region/3));for(const item of MW.items.filter(i=>supplies?i.type==='use':i.type!=='use'&&i.tier<=tier&&(!i.job||i.job===this.p.job))){const owned=this.p.owned.includes(item.id),c=this.card(item.name,`${item.desc} · ${item.price}냥${owned?' · 보유':''}`);this.button(c,owned?'보유 중':'구매',()=>{if(item.type!=='use'&&this.p.owned.includes(item.id)){this.notify('이미 보유한 장비입니다.');return;}if(this.p.gold<item.price){this.notify('소지금이 부족합니다.');return;}this.p.gold-=item.price;if(item.type==='use')this.p.bag[item.id]++;else{this.p.owned.push(item.id);this.p.equip[item.type]=item.id;}this.save();this.notify(item.name+' 구매'+(item.type==='use'?'':' · 장착 완료'));this.shop(n);});box.append(c);}this.show(n.name,`${supplies?'물약 상점':'무기·방어구 상점'} · ${this.p.gold}냥`,box,supplies?[['휴식 · 무료 회복',()=>{this.p.hp=this.stats().hp;this.p.mp=100;this.notify('생명력과 기력 회복');dialog.close();}]]:[]);}
 forge(n){const price=80+this.p.upgrade*70,ore=2+Math.floor(this.p.upgrade/2);this.show(n.name,'별철 공방',`무기 강화 +${this.p.upgrade} / 10 · 강화마다 공격 +5. 비용 ${price}냥, 강화석 ${ore}개.\n보유 강화석 ${this.p.bag.ore} / 약초 ${this.p.bag.herb}. 약초 4개로 회복약 1병을 만듭니다.`,[['검 강화',()=>{if(!this.p.equip.weapon){this.notify('상점에서 무기를 구매하고 장착하세요.');return;}if(this.p.upgrade>=10){this.notify('최대 강화 단계입니다.');return;}if(this.p.gold<price||this.p.bag.ore<ore){this.notify('소지금 또는 강화석이 부족합니다.');return;}this.p.gold-=price;this.p.bag.ore-=ore;this.p.upgrade++;this.forge(n);} ],['회복약 제작 · 약초 4',()=>{if(this.p.bag.herb<4){this.notify('약초가 부족합니다.');return;}this.p.bag.herb-=4;this.p.bag.potion++;this.forge(n);}],['강화석 판매 · 개당 18냥',()=>{if(this.p.bag.ore<1)return;this.p.bag.ore--;this.p.gold+=18;this.forge(n); }]]);}
 sideNeed(i){return[48+this.p.region*4,16,6][i];}
 sideMenu(n){const box=this.content(),r=this.p.region;this.p.side[r].forEach((s,i)=>{const kind=['사냥터 정화','기억과 약초 수집','잊힌 보물함 조사'][i],c=this.card(MW.sideTitles[r][i],`${n.name}의 사연 · ${['길을 잃은 사람들이 돌아올 수 있도록 주변 위협을 거둡니다.','기억하지 못하는 이에게도 약초의 향기는 남습니다.','남겨진 유품을 찾아 이름이 지워진 이들을 기록합니다.'][i]}\n${kind}: ${Math.min(s.count,this.sideNeed(i))} / ${this.sideNeed(i)} · 보상 ${220+r*65}냥, 강화석 3`);if(s.done){const p=document.createElement('p');p.textContent='✓ 의뢰 완료';c.append(p);}else if(!s.accepted)this.button(c,'의뢰 수락',()=>{s.accepted=true;if(i===1)s.count=this.q().memories.length;if(i===2)s.count=this.q().chests.length;this.sideMenu(n);});else if(s.count>=this.sideNeed(i))this.button(c,'보상 받기',()=>{s.done=true;this.reward(180+r*30,220+r*65);this.p.bag.ore+=3;this.p.log.push(MW.sideTitles[r][i]+' · 주민의 이름을 기억했다');this.sideMenu(n);});else{const p=document.createElement('p');p.textContent='진행 중 · 수락 후의 행동이 기록됩니다.';c.append(p);}box.append(c);});this.show(n.name,'주민들의 이야기',box);}
 landmark(o){const s=this.step(),q=this.q(),r=MW.regions[this.p.region];if(s?.kind==='scout'&&[0,1,3].includes(o.index)&&!q.seen.includes(o.id)){q.seen.push(o.id);this.count('scout');this.show(o.name,'남겨진 기록',r.story+'\n기록의 한 장을 의뢰 수첩에 남겼습니다.');return;}if(o.index===2&&s?.kind==='puzzle'){this.puzzle=[];this.puzzleMenu();return;}if(o.index===3&&s?.kind==='escort'){if(this.escort){this.notify('순례자가 당신을 따라옵니다. 마을의 안내자에게 돌아가세요.');return;}this.show('길 잃은 순례자','집으로 가는 길','당신이 가까이 있을 때 순례자가 따라옵니다. 멀어지면 기다립니다. 매복을 막으며 서쪽 마을로 돌아가세요. 순례자가 쓰러지면 야영지에서 다시 시작할 수 있습니다.',[['함께 돌아간다',()=>{dialog.close();this.escort={x:o.x,y:o.y,hp:300,ambush:0};}]]);return;}if(o.index===1&&s?.kind==='defend'){if(this.event){this.notify('봉화의 불을 지켜주세요.');return;}dialog.close();this.event={wave:0,kills:0,x:o.x,y:o.y};this.nextWave();return;}this.show(o.name,'길 위의 기록',o.index===5?'달의 문은 지역의 이름들을 잇습니다. 세계 지도(M)에서 방문한 마을로 돌아갈 수 있습니다.':r.subtitle+'\n'+r.story);}
 puzzleMenu(){const r=MW.regions[this.p.region],symbols={1:'해',2:'별',3:'달'},clue=r.puzzle.map(x=>symbols[x]).join(' → ');this.show('잊힌 제단','세 빛의 순서',`비문: “${clue}의 길을 따른다.”\n선택: ${this.puzzle.map(x=>symbols[x]).join(' → ')||'아직 없음'}\n기호 셋을 비문의 순서대로 밝히세요.`,[1,2,3].map(n=>[symbols[n]+'를 밝힌다',()=>{this.puzzle.push(n);if(this.puzzle.length===3){const ok=this.puzzle.every((v,i)=>v===r.puzzle[i]);if(ok){dialog.close();this.count('puzzle');this.notify('제단에 빛이 돌아왔습니다.');}else{this.puzzle=[];this.notify('빛이 흩어졌습니다. 비문의 순서를 다시 읽으세요.');this.puzzleMenu();}}else this.puzzleMenu();}]));}
 nextWave(){const ev=this.event;if(!ev)return;ev.wave++;ev.kills=0;for(let i=0;i<10+Math.floor(this.p.region/3);i++){const angle=i/12*Math.PI*2;this.spawn(ev.x+Math.cos(angle)*220,ev.y+Math.sin(angle)*220,{event:true,type:i%3});}this.notify(`봉화 방어 · ${ev.wave}번째 습격`);}
 startTower(floor){this.event=null;this.escort=null;this.tower={floor,wave:0,kills:0,required:32+(floor%5===0?1:0)};this.enemies=[];this.p.x=40*48;this.p.y=28*48;this.p.hp=this.stats().hp;this.p.mp=100;this.towerWave();this.ui();}
 towerWave(){if(!this.tower)return;this.tower.wave++;for(let i=0;i<8;i++)this.spawn(this.p.x+Math.cos(i/8*Math.PI*2)*230,this.p.y+Math.sin(i/8*Math.PI*2)*230,{tower:true,type:i%3});if(this.tower.wave===4&&this.tower.floor%5===0)this.spawn(this.p.x+190,this.p.y,{tower:true,boss:true,type:3,name:'시련의 수호자'});}
 target(){if(this.tower)return null;if(this.dungeon)return this.world.objects.find(o=>o.type==='landmark'&&!this.dungeon.seals.includes(o.id))||this.enemies.find(e=>e.boss&&!e.dead);const s=this.step();if(!s)return this.world.objects.find(o=>o.id==='exit');const obj=i=>this.world.objects.find(o=>o.id==='land'+i);if(s.kind==='talk'||s.kind==='return')return this.world.npcs[0];if(s.kind==='scout')return this.world.objects.find(o=>o.type==='landmark'&&[0,1,3].includes(o.index)&&!this.q().seen.includes(o.id));if(s.kind==='kill')return this.enemies.find(e=>!e.dead&&!e.boss);if(s.kind==='collect')return this.world.objects.find(o=>o.type==='memory'&&!this.collected.has(o.id));if(s.kind==='puzzle')return obj(2);if(s.kind==='escort')return this.escort?this.world.npcs[0]:obj(3);if(s.kind==='defend')return obj(1);if(s.kind==='boss')return this.enemies.find(e=>e.boss&&!e.dead);return null;}
 journal(){const box=this.content();for(let i=0;i<12;i++){const q=this.p.progress[i],c=this.card(`${i+1}장 · ${MW.regions[i].name}`,`${q.step} / 9 이야기 의뢰 완료 · ${MW.regions[i].subtitle}`);if(i<=this.p.unlocked){const p=document.createElement('p');p.textContent=MW.steps.map((s,j)=>(j<q.step?'✓ ':j===q.step?'◆ ':'○ ')+s.title).join(' · ');c.append(p);}box.append(c);}const log=this.card('여행 기록',this.p.log.slice(-12).join('\n')||'첫 번째 이름을 찾으세요.');box.append(log);this.show('여행자의 수첩','108개 이야기 의뢰 · 36개 주민 의뢰',box,[['현재 지역 주민 의뢰',()=>this.sideMenu(this.world.npcs[3])]]);}
 worldMap(){const box=this.content();MW.regions.forEach((r,i)=>{const c=this.card(`${String(i+1).padStart(2,'0')} · ${r.name}`,`${r.subtitle} · ${i<=this.p.unlocked?'여행 가능':'이전 지역 이야기 완료 후 개방'}`);if(i<=this.p.unlocked)this.button(c,i===this.p.region?'현재 지역':'마을로 이동',()=>{if(this.event||this.escort||this.tower||this.dungeon){this.notify('호위·방어·탑을 마치거나 설정에서 포기한 후 이동하세요.');return;}dialog.close();this.enter(i);});box.append(c);});this.show('열두 조각의 길','세계 지도',box);}
 preview(box,p=this.p){const canvas=document.createElement('canvas');canvas.width=160;canvas.height=180;canvas.className='character-preview';canvas.setAttribute?.('aria-label',(MW.jobs[p.job]||MW.jobs.traveler).name+' 장비 외형');const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.scale(2,2);c.drawImage(this.renderer.player(p,0,0),0,0);box.append(canvas);}
 jobMenu(){const box=this.content();box.append(this.card('직업의 길 · 현재 '+MW.jobs[this.p.job].name,'레벨 3부터 전직할 수 있습니다. 마을에서 무료로 직업을 바꿀 수 있으며, 직업마다 처음 선택할 때 수련 장비를 지급합니다. 기존 장비는 가방에 보관됩니다.'));for(const id of ['warrior','archer','mage']){const j=MW.jobs[id],c=this.card(j.name,j.detail+' · 기술: '+j.skill+' · 마력 25');this.preview(c,{job:id,equip:{weapon:id==='warrior'?'weapon1':id+'weapon1',armor:id+'armor1'}});this.button(c,this.p.job===id?'현재 직업':'전직하기',()=>{if(this.p.job===id){this.notify('이미 선택한 직업입니다.');return;}if(this.p.level<3){this.notify('레벨 3부터 전직할 수 있습니다.');return;}if(this.dungeon||this.tower||this.p.x>=22*48){this.notify('마을로 돌아온 뒤 전직하세요.');return;}this.show(j.name+' 전직','직업을 바꿀까요?',j.detail+'\n현재 장비는 가방에 보관하고 이 직업의 수련 장비를 장착합니다.',[['전직 확정',()=>this.changeJob(id)],['직업 목록',()=>this.jobMenu()]]);});box.append(c);}this.show('수련관 · 직업의 길','전사 / 궁수 / 마법사',box);}
 changeJob(id){if(!['warrior','archer','mage'].includes(id)||this.p.level<3||this.dungeon||this.tower||this.p.x>=22*48)return;this.p.job=id;for(const [type,item] of [['weapon',id==='warrior'?'weapon1':id+'weapon1'],['armor',id+'armor1']]){if(!this.p.owned.includes(item))this.p.owned.push(item);this.p.equip[type]=item;}this.p.hp=this.stats().hp;this.p.mp=100;this.cool={attack:0,skill:0,dash:0};this.slash=0;this.p.log.push(MW.jobs[id].name+'의 길을 선택했습니다.');this.save();this.ui();this.notify(MW.jobs[id].name+' 전직 · 수련 장비 장착');this.jobMenu();}
 inventory(){const box=this.content();this.preview(box);for(const t of ['weapon','armor','charm']){const item=MW.items.find(i=>i.id===this.p.equip[t]),c=this.card({weapon:'무기',armor:'방어구',charm:'장신구'}[t],item?item.name+' · '+item.desc:'미장착');if(item)this.button(c,'장착 해제',()=>{this.p.equip[t]=null;this.p.hp=Math.min(this.p.hp,this.stats().hp);this.save();this.ui();this.inventory();});box.append(c);}for(const item of MW.items.filter(i=>this.p.owned.includes(i.id))){const c=this.card(item.name,item.desc),allowed=!item.job||item.job===this.p.job;this.button(c,allowed?'장착':'다른 직업 전용',()=>{if(!allowed){this.notify(MW.jobs[item.job].name+' 전용 장비입니다.');return;}this.p.equip[item.type]=item.id;this.p.hp=Math.min(this.p.hp,this.stats().hp);this.save();this.ui();this.inventory();});box.append(c);}for(const item of MW.items.filter(i=>i.type==='use')){const c=this.card(item.name,item.desc+' · '+this.p.bag[item.id]+'개');this.button(c,'사용',()=>{this.use(item.id);this.inventory();});box.append(c);}box.append(this.card('제작 재료','강화석 '+this.p.bag.ore+' · 약초 '+this.p.bag.herb+' · 무기 강화 +'+this.p.upgrade));this.show('여행자의 가방',MW.jobs[this.p.job].name+' · 장비와 전투 보급품',box);}
 settings(){this.show('여행자의 쉼표','설정과 저장',`기기 저장: ${this.saveOK?'정상':'사용 불가'}${this.p.savedAt?' · 마지막 저장 '+new Date(this.p.savedAt).toLocaleTimeString('ko-KR',{hour12:false}):''}. 이 기기의 현재 브라우저에 자동 저장하며 서버로 전송하지 않습니다. 같은 브라우저로 다시 열면 이어집니다. 브라우저 데이터 삭제 시 저장도 지워집니다. 다른 기기로 옮길 때는 저장 파일을 내보내세요.\n\n실제 플레이 ${Math.floor(this.p.seconds/60)}분. 대화·일시정지·숨겨진 탭 시간은 제외합니다. 10시간 이상의 탐험을 목표로 구성했으며 실제 완주 시간은 플레이 방식에 따라 달라집니다.`,[['지금 기기에 저장',()=>{this.save();this.ui();this.notify(this.saveOK?'이 기기에 저장했습니다.':'기기 저장에 실패했습니다. 저장 파일을 내보내세요.');this.settings();}],['소리 '+(this.sound?'끄기':'켜기'),()=>{this.sound=!this.sound;this.beep(440);this.settings();}],['저장 파일 내보내기',()=>{this.save();const blob=new Blob([JSON.stringify(this.p,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='moonwind-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}],['저장 파일 불러오기',()=>$('#import').click()],['활동 포기하고 마을로',()=>{dialog.close();this.enter(this.p.region);this.notify('활동을 포기했습니다. 이야기 진행은 유지됩니다.');}],['새 여정',()=>this.show('새 여정','현재 저장을 초기화할까요?','이 브라우저의 V2 진행이 초기화됩니다. 필요하면 저장 파일을 먼저 내보내세요.',[['초기화',()=>{this.p=this.fresh();this.enter(0);dialog.close();this.save();}]])]]);}

 expeditionMenu(n){const r=this.p.region,best=this.p.expeditions[r];this.show(n.name,'이름의 미궁 · 지역 원정', '각 지역에 6층짜리 미궁이 있습니다. 세 봉인을 조사하고 수호자를 물리쳐 다음 층으로 내려갑니다. 원정 지도는 마을과 분리된 여섯 방 구조입니다. 기록과 최초 보상은 저장됩니다.\n현재 지역 '+best+' / 6층 · 세계 전체 '+this.p.expeditions.reduce((a,b)=>a+b,0)+' / 72층',[['지역 원정 '+Math.min(6,best+1)+'층 시작',()=>{dialog.close();this.startDungeon(Math.min(6,best+1));}],...(this.p.unlocked>=2?[['30층 시련의 탑',()=>{dialog.close();this.startTower(1);}]]:[])]);}
 startDungeon(floor){this.event=null;this.tower=null;this.escort=null;this.dungeon={floor,seals:[],bossSpawned:false,finished:false};this.world=MW.makeInstance(this.p.region,floor);this.renderer.setWorld(this.world);this.enemies=[];this.telegraphs=[];this.collected=new Set();this.p.x=13*48;this.p.y=16*48;this.p.hp=this.stats().hp;this.p.mp=100;this.world.rooms.slice(1).forEach(([x,y],room)=>{for(let i=0;i<9;i++)this.spawn((x-4+i%3*3)*48,(y-3+Math.floor(i/3)*3)*48,{expedition:true,type:(room+i+floor)%3});});this.ui();}
 dungeonInteract(){const o=this.world.objects.find(o=>Math.hypot(o.x-this.p.x,o.y-this.p.y)<105);if(!o)return;if(o.id==='leave'){this.show('원정 귀환','미궁을 떠날까요?','현재 층의 전투는 초기화됩니다. 완료한 층과 보상은 유지됩니다.',[['마을로 귀환',()=>{dialog.close();this.enter(this.p.region);}]]);return;}if(this.dungeon.seals.includes(o.id)){this.notify('이미 열린 봉인입니다.');return;}if(this.enemies.some(e=>!e.dead&&Math.hypot(e.x-o.x,e.y-o.y)<250)){this.notify('봉인 주변의 적을 먼저 물리치세요.');return;}this.dungeon.seals.push(o.id);this.notify(o.name+' 해제');if(this.dungeon.seals.length===3){this.dungeon.bossSpawned=true;this.spawn(59*48,37*48,{boss:true,expedition:true,type:3,name:MW.regions[this.p.region].boss+'의 기억'});this.notify('깊은 방에 수호자의 기억이 깨어났습니다.');}}
 updateDungeon(){if(!this.dungeon||!this.dungeon.bossSpawned||this.dungeon.finished||this.enemies.some(e=>e.expedition&&e.boss&&!e.dead))return;this.dungeon.finished=true;const floor=this.dungeon.floor,r=this.p.region;if(floor>this.p.expeditions[r]){this.p.expeditions[r]=floor;this.reward(260+r*45+floor*20,220+r*65+floor*35);this.p.bag.ore+=5;this.p.bag.potion+=2;}this.save();this.show('이름의 미궁',floor===6?'지역 원정 완수':floor+'층의 기억을 되찾았다','지역 기록 '+this.p.expeditions[r]+' / 6층. 최초 완료 보상으로 강화석 5개와 회복약 2개를 받습니다.',floor<6?[['다음 층',()=>{dialog.close();this.startDungeon(floor+1);} ],['마을로 귀환',()=>{dialog.close();this.enter(r);}]]:[['마을로 귀환',()=>{dialog.close();this.enter(r);}]]);}
 bind(){window.addEventListener('keydown',e=>{if(dialog.open)return;const k=e.key.startsWith('Arrow')?e.key:e.key.toLowerCase();if(e.target?.closest?.('.screen-menu')&&(k===' '||k==='enter'||(k.startsWith('Arrow')&&document.querySelector('.menu-group[open]'))))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();this.keys.add(k);this.lastInput=this.time;if(e.repeat)return;const actions={q:()=>this.attack(true),r:()=>this.dash(),e:()=>this.interact(),'1':()=>this.use('potion'),'2':()=>this.use('ether'),j:()=>this.journal(),m:()=>this.worldMap(),i:()=>this.inventory()};actions[k]?.();});window.addEventListener('keyup',e=>this.keys.delete(e.key.startsWith('Arrow')?e.key:e.key.toLowerCase()));window.addEventListener('blur',()=>{this.keys.clear();this.resetStick?.();this.save();});document.addEventListener('visibilitychange',()=>{this.keys.clear();this.resetStick?.();this.save();});$('#close').onclick=()=>dialog.close();$('#journal').onclick=()=>this.journal();$('#world').onclick=()=>this.worldMap();$('#bag').onclick=()=>this.inventory();$('#job').onclick=()=>this.jobMenu();$('#characterstatus').onclick=()=>this.show('캐릭터','능력치와 여행 기록',`공격 / 방어 ${$('#combat').textContent}\n${$('#equipment').textContent}\n${$('#playtime').textContent}\n${$('#save-status').textContent}`);const menus=[...document.querySelectorAll('.menu-group')];for(const menu of menus)menu.addEventListener('toggle',()=>{if(menu.open){this.keys.clear();this.resetStick?.();for(const other of menus)if(other!==menu)other.open=false;}});for(const item of document.querySelectorAll('.menu-list button'))item.addEventListener('click',()=>menus.forEach(m=>m.open=false));document.addEventListener('pointerdown',e=>{if(!e.target.closest?.('.screen-menu'))menus.forEach(m=>m.open=false);});window.addEventListener('keydown',e=>{if(e.key==='Escape')menus.forEach(m=>m.open=false);});$('#settings').onclick=()=>this.settings();$('#potion').onclick=()=>this.use('potion');$('#ether').onclick=()=>this.use('ether');$('#skill').onclick=()=>this.attack(true);$('#track').onclick=()=>{this.tracking=!this.tracking;this.notify(this.tracking?'미니맵의 금색 표식이 목표입니다.':'목표 표시 숨김');};$('#help').onclick=()=>this.show('조작 안내','여행을 시작하세요','모바일: 왼쪽 원형 조작키를 원하는 방향으로 드래그해 이동합니다. 손을 떼면 멈춥니다. 오른쪽 큰 버튼은 주민 앞에서 대화, 표식 앞에서 조사, 전투 중에는 공격으로 바뀝니다. 길게 누르면 연속 공격합니다. 이동과 공격을 동시에 누를 수 있습니다. 가로·세로 회전을 지원합니다. 화면 위 아이콘에서 여행·캐릭터·시스템 메뉴를 여세요.\n\nPC: WASD / 방향키 이동 · SPACE 공격 / 대화 / 조사 · Q 달빛베기 (기력 25, 재사용 4초) · R 바람걸음 (기력 12, 재사용 2초, 회피) · E 대화 / 조사 · 1 회복약 · 2 기력약 · J 수첩 · M 지도 · I 가방. 마을에서는 회복됩니다. 공격은 주변 적에게 적중합니다. 붉은 원은 공격 예고입니다. 미니맵의 금색 표식을 따라가세요.');const stick=$('#joystick'),thumb=$('#stick-thumb'),directions=['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'];let stickPointer=null;this.resetStick=()=>{stickPointer=null;directions.forEach(k=>this.keys.delete(k));thumb.style.transform='translate(0px,0px)';};const steer=e=>{const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.hypot(dx,dy),radius=r.width*.28,f=d>radius?radius/d:1;thumb.style.transform='translate('+dx*f+'px,'+dy*f+'px)';directions.forEach(k=>this.keys.delete(k));if(d>r.width*.1){if(dx/d>.38)this.keys.add('ArrowRight');if(dx/d<-.38)this.keys.add('ArrowLeft');if(dy/d>.38)this.keys.add('ArrowDown');if(dy/d<-.38)this.keys.add('ArrowUp');this.lastInput=this.time;}};stick.addEventListener('pointerdown',e=>{if(stickPointer!==null||dialog.open)return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);steer(e);});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer){e.preventDefault();steer(e);}});for(const event of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(event,e=>{if(e.pointerId===stickPointer)this.resetStick();});for(const b of document.querySelectorAll('[data-action]')){if(b.dataset.action==='attack'){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);this.keys.add(' ');this.lastInput=this.time;this.primaryAction();});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>this.keys.delete(' '));b.onclick=e=>{if(e.detail===0)this.primaryAction();};}else b.onclick=()=>({skill:()=>this.attack(true),dash:()=>this.dash(),interact:()=>this.interact()})[b.dataset.action]();}const canvas=$('#game');const resize=()=>{if(typeof canvas.getBoundingClientRect!=='function')return;const rect=canvas.getBoundingClientRect(),width=Math.max(1,Math.round(rect.width)),height=Math.max(1,Math.round(rect.height));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;this.keys.clear();this.resetStick?.();}};if(typeof ResizeObserver==='function')new ResizeObserver(resize).observe(canvas);window.addEventListener('resize',resize);resize();$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error();const s=JSON.parse(await f.text());if(!this.valid(s))throw Error();this.show('불러오기','현재 진행을 저장 파일로 바꿀까요?',`${Math.floor(s.seconds/60)}분 · ${MW.regions[s.region].name} · Lv.${s.level}`,[['불러오기',()=>{this.p=s;this.p.job??='traveler';this.p.expeditions??=Array(12).fill(0);dialog.close();this.enter(s.region,!s.activity);this.save();}]]);}catch{this.notify('유효한 V2 저장 파일이 아닙니다. 현재 진행을 유지합니다.');}e.target.value='';};}
 update(dt){this.time+=dt;if(this.time-this.lastInput<30||this.enemies.some(e=>!e.dead&&Math.hypot(e.x-this.p.x,e.y-this.p.y)<310))this.p.seconds+=dt;this.invuln=Math.max(0,this.invuln-dt);this.slash=Math.max(0,this.slash-dt);for(const k of Object.keys(this.cool))this.cool[k]=Math.max(0,this.cool[k]-dt);for(const k of ['meal','ward'])this.p.buffs[k]=Math.max(0,this.p.buffs[k]-dt);let dx=(this.keys.has('ArrowRight')||this.keys.has('d')?1:0)-(this.keys.has('ArrowLeft')||this.keys.has('a')?1:0),dy=(this.keys.has('ArrowDown')||this.keys.has('s')?1:0)-(this.keys.has('ArrowUp')||this.keys.has('w')?1:0);this.moving=!!(dx||dy);if(this.moving){const n=Math.hypot(dx,dy);this.move(this.p,dx/n*190*dt,dy/n*190*dt);this.face=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);}if(this.keys.has(' '))this.primaryAction();this.p.mp=Math.min(100,this.p.mp+5*dt);if(this.p.x<22*48&&!this.tower&&!this.dungeon)this.p.hp=Math.min(this.stats().hp,this.p.hp+14*dt);
 for(const e of this.enemies){if(e.dead){if(Number.isFinite(e.dead)){e.dead-=dt;if(e.dead<=0){e.dead=0;e.hp=e.max;e.x=e.homeX;e.y=e.homeY;}}continue;}e.cd-=dt;const d=Math.hypot(this.p.x-e.x,this.p.y-e.y),aggro=(this.p.x>23*48||e.tower||e.event||e.expedition)&&d<(e.boss?420:310);if(aggro){if(d>45&&e.cast<=0)this.move(e,(this.p.x-e.x)/d*(e.boss?78:85+this.p.region*2)*dt,(this.p.y-e.y)/d*(e.boss?78:85+this.p.region*2)*dt);if(e.cd<=0){if((e.boss&&d<350)||(e.type===1&&d<250)){e.cast=.9;if(e.boss&&e.hp<e.max*.5&&!e.phase2){e.phase2=true;for(let i=0;i<3;i++)this.spawn(e.x+(i-1)*85,e.y+100,{type:i,event:e.event,tower:e.tower,expedition:e.expedition});this.notify('수호자가 두 번째 힘을 드러냅니다.');}if(e.boss&&this.p.region%3===1){for(let i=0;i<3;i++)this.telegraphs.push({x:this.p.x+(i-1)*100,y:this.p.y,radius:65,life:1.4,damage:28+this.p.region*8,source:e});}if(e.boss&&this.p.region%3===2){for(let i=0;i<5;i++){const a=i/5*Math.PI*2;this.telegraphs.push({x:e.x+Math.cos(a)*150,y:e.y+Math.sin(a)*150,radius:65,life:1.5,damage:30+this.p.region*7,source:e});}}this.telegraphs.push({x:this.p.x,y:this.p.y,radius:e.boss?110:48,life:e.boss?1.1:.85,damage:e.boss?38+this.p.region*8:18+this.p.region*4,source:e});e.cd=e.boss?2.8:3;}else if(d<62){this.hurt(15+this.p.region*5);e.cd=1.1;}}}e.cast=Math.max(0,e.cast-dt);}
 for(const t of this.telegraphs){t.life-=dt;if(t.life<=0&&t.source&&!t.source.dead&&Math.hypot(this.p.x-t.x,this.p.y-t.y)<t.radius)this.hurt(t.damage);}this.telegraphs=this.telegraphs.filter(t=>t.life>0);for(const f of this.fx){f.life-=dt;f.y-=dt*27;}this.fx=this.fx.filter(f=>f.life>0);
 if(this.escort){const e=this.escort,d=Math.hypot(this.p.x-e.x,this.p.y-e.y);if(d>42&&d<320)this.move(e,(this.p.x-e.x)/d*118*dt,(this.p.y-e.y)/d*118*dt);if(Math.hypot(e.x-11*48,e.y-28*48)<130){this.escort=null;this.count('escort');}else{for(const mob of this.enemies)if(!mob.dead&&Math.hypot(mob.x-e.x,mob.y-e.y)<55)e.hp-=dt*(5+this.p.region);if(e.hp<=0){this.escort=null;this.notify('순례자가 야영지로 돌아갔습니다. 다시 호위할 수 있습니다.');}}}
 if(this.event&&this.enemies.filter(e=>e.event&&!e.dead).length===0){this.q().count=this.event.wave;if(this.event.wave>=5){this.event=null;this.advance();}else this.nextWave();}
 if(this.tower&&this.enemies.filter(e=>e.tower&&!e.dead).length===0){if(this.tower.wave<4)this.towerWave();else{const floor=this.tower.floor;this.p.towerBest=Math.max(this.p.towerBest,floor);if(!this.p.towerRewards.includes(floor)){this.p.towerRewards.push(floor);this.reward(300+floor*25,180+floor*45);this.p.bag.ore+=3;}this.p.hp=this.stats().hp;this.p.mp=100;this.show('시련의 문지기',floor===30?'30층 시련 완수':floor+'층 돌파',`최고 기록 ${this.p.towerBest}층. 층 보상은 최초 1회 지급됩니다. 다음 층에서는 적의 생명력이 증가합니다.`,floor<30?[['다음 층',()=>{dialog.close();this.startTower(floor+1);} ],['마을로 돌아가기',()=>{dialog.close();this.enter(this.p.region);}]]:[['마을로 돌아가기',()=>{dialog.close();this.enter(this.p.region);}]]);}}
 // Collections made before their story step count when that step opens.
 if(this.step()?.kind==='collect'&&this.q().memories.length>=this.required())this.advance();if(this.step()?.kind==='boss'&&this.q().boss)this.advance();this.updateDungeon();this.saveTimer+=dt;this.uiTimer+=dt;if(this.saveTimer>5){this.saveTimer=0;this.save();}if(this.uiTimer>.2){this.uiTimer=0;this.ui();}}
 ui(){const mode=this.primaryMode();$('#actionicon').textContent={attack:'⚔',talk:'☏',inspect:'⌕'}[mode];$('#actiontext').textContent={attack:'공격',talk:'대화',inspect:'조사'}[mode];const s=this.stats(),q=this.q(),r=MW.regions[this.p.region],step=this.step();$('#mapname').textContent=this.dungeon?r.name+' · 이름의 미궁 '+this.dungeon.floor+'층':r.name;$('#mapdesc').textContent=r.subtitle;$('#chapter').textContent=`CHAPTER ${String(this.p.region+1).padStart(2,'0')} / 12`;$('#level').textContent='Lv. '+this.p.level;$('#rank').textContent=(MW.jobs[this.p.job]||MW.jobs.traveler).name+(this.p.progress[11].step===9?' · 기록자':'');$('#hptext').textContent=`${Math.ceil(this.p.hp)} / ${s.hp}`;$('#hp').style.width=Math.max(0,this.p.hp/s.hp*100)+'%';$('#mptext').textContent=Math.floor(this.p.mp)+' / 100';$('#mp').style.width=this.p.mp+'%';$('#xptext').textContent=this.p.xp+' / '+this.needXP();$('#xp').style.width=Math.min(100,this.p.xp/this.needXP()*100)+'%';$('#gold').textContent=this.p.gold+'냥';$('#combat').textContent=s.atk+' / '+s.def;$('#questtitle').textContent=this.dungeon?'원정: 세 봉인과 수호자':step?`${q.step+1}. ${step.title}`:'지역 이야기 완료';$('#quest').textContent=this.dungeon?'세 방의 봉인을 조사한 뒤 깊은 방의 수호자를 물리치세요. 붉은 원정 문으로 귀환할 수 있습니다.':step?step.detail:'다음 지역을 여행하거나 주민 의뢰와 시련의 탑에 도전하세요.';$('#questprogress').textContent=this.dungeon?`봉인 ${this.dungeon.seals.length} / 3 · 층 ${this.dungeon.floor} / 6`:step?`${Math.min(q.count,this.required())} / ${this.required()} · 미니맵 금색 표식`:'달 조각: '+r.relic;$('#pots').textContent=this.p.bag.potion;$('#ethers').textContent=this.p.bag.ether;$('#skilltext').textContent=this.cool.skill>0?Math.ceil(this.cool.skill)+'초':(MW.jobs[this.p.job]||MW.jobs.traveler).skill;$('#skill').setAttribute?.('aria-label',(MW.jobs[this.p.job]||MW.jobs.traveler).skill+' 사용');$('#equipment').textContent=['weapon','armor','charm'].map(t=>MW.items.find(i=>i.id===this.p.equip[t])?.name||'미장착').join(' · ');$('#save-status').textContent=this.saveOK?'기기 자동 저장'+(this.p.savedAt?' · '+new Date(this.p.savedAt).toLocaleTimeString('ko-KR',{hour12:false}):''):'저장 불가 · 설정에서 파일을 내보내세요';$('#playtime').textContent=`실제 플레이 ${Math.floor(this.p.seconds/3600)}시간 ${Math.floor(this.p.seconds/60)%60}분 · 최고 시련 ${this.p.towerBest}층`;}
}
